// Modules generated from react-icons by the plugin in vite.config.ts.

declare module 'virtual:react-icons-index' {
  /** Every icon name by family, comma separated and sorted: `{ tb: 'TbAB,TbABOff,…' }`. */
  const index: Record<string, string>;
  export default index;
}

declare module 'virtual:react-icons-chunks' {
  /** Per family, the chunks in order: the first icon name of each one and its loader. */
  const chunks: Record<string, [first: string, load: () => Promise<{ default: Record<string, import('react-icons').IconTree> }>][]>;
  export default chunks;
}
